-- Verifica propiedad ANTES de insertar o borrar. Un UUID aislado nunca basta.
DO $$
DECLARE r record; existente jsonb;
BEGIN
 FOR r IN SELECT * FROM rev_fixture ORDER BY orden LOOP
  EXECUTE format('SELECT to_jsonb(t) FROM %I t WHERE %I = $1::uuid',r.tabla,r.pk)
    INTO existente USING r.datos->>r.pk;
  IF existente IS NOT NULL AND NOT existente @> r.identidad THEN
   RAISE EXCEPTION 'SGP-TEST-REV: colisión o identidad modificada en % (%); no se tocará',r.tabla,r.clave;
  END IF;
 END LOOP;
END $$;
